def _decode_recovery_index_migration_state(text, before, after, steps):
    """Validate a previous execute_recovery_index_migration state document.

    ``before``/``after`` are the canonical index documents and ``steps`` the
    plan's full ``(kind, batch_id, status)`` step list. Returns
    ``(status, confirmed)`` ...
    """
    try:
        node = _parse_json_node(text, _skip_json_ws(text, 0))
    except ValueError as exc:
        raise ValueError(f"state is not a valid JSON document ({exc})") from exc
    if _skip_json_ws(text, node[2]) != len(text):
        raise ValueError("state has trailing data after the JSON document")
    top = node[0]
    if not isinstance(top, dict) or list(top) != ["status", "confirmed", "steps", "index", "complete"]:
        raise ValueError('state must be a JSON object with exactly the keys "status", "confirmed", "steps", "index" and "complete"')
    status = top["status"][0]
    if status not in ("pending", "applied", "unchanged"):
        raise ValueError('state "status" must be "pending", "applied" or "unchanged"')
    confirmed = top["confirmed"][0]
    if isinstance(confirmed, bool) or not isinstance(confirmed, int) or confirmed < 0 or confirmed > len(steps):
        raise ValueError('state "confirmed" must be between zero and the number of migration steps')
    step_nodes = top["steps"][0]
    if not isinstance(step_nodes, list) or len(step_nodes) != confirmed:
        raise ValueError('state "steps" must hold one step per confirmed migration step')
    state_steps = []
    for step_node in step_nodes:
        row = step_node[0]
        if not isinstance(row, list) or len(row) != 3:
            raise ValueError("each state step must be a three-item array [kind, id, status]")
        kind, batch_id, row_status = row[0][0], row[1][0], row[2][0]
        if kind not in ("rollback", "pending"):
            raise ValueError('state step kind must be "rollback" or "pending"')
        if not isinstance(batch_id, str) or not isinstance(row_status, str):
            raise ValueError("state step id and status must be str")
        state_steps.append((kind, batch_id, row_status))
    if tuple(state_steps) != tuple(steps[:confirmed]):
        raise ValueError('state "steps" must be a confirmed prefix of the plan\'s migration steps')
    index_node = top["index"]
    if not isinstance(index_node[0], dict):
        raise ValueError('state "index" must be a JSON object')
    index = text[index_node[1]:index_node[2]]
    complete = top["complete"][0]
    if not isinstance(complete, bool):
        raise ValueError('state "complete" must be a boolean')
    if complete != (confirmed == len(steps)):
        raise ValueError('state "complete" does not match the confirmed prefix')
    if complete:
        if index != after:
            raise ValueError('a completed state must embed the after index')
        if status == "pending":
            raise ValueError('a completed state may not be "pending"')
    else:
        if index != before:
            raise ValueError('an unfinished state must embed the before index')
        if status != "pending":
            raise ValueError('an unfinished state must be "pending"')
    canonical = _format_recovery_index_migration_state(status, state_steps, index, complete)
    if canonical != text:
        raise ValueError("state is not its canonical encoding")
    return status, confirmed
```

