def execute_recovery_index_migration(before, after, plan, current, state=None, max_steps=None) -> str:
    if not isinstance(before, str):
        raise TypeError("before must be a str")
    if not isinstance(after, str):
        raise TypeError("after must be a str")
    if not isinstance(plan, str):
        raise TypeError("plan must be a str")
    if not isinstance(current, str):
        raise TypeError("current must be a str")
    if state is not None and not isinstance(state, str):
        raise TypeError("state must be None or a str")
    if max_steps is not None:
        if isinstance(max_steps, bool) or not isinstance(max_steps, int):
            raise TypeError("max_steps must be None or a non-bool int")
        if max_steps < 0:
            raise ValueError("max_steps must be non-negative")

    expected = plan_recovery_index_migration(before, after)
    if plan != expected:
        raise ValueError("plan does not match plan_recovery_index_migration(before, after)")
    _decode_merged_recovery_index(current)

    document = json.loads(plan)
    steps = [("rollback", batch_id, row_status) for batch_id, row_status in document["rollback"]] + \
            [("pending", batch_id, row_status) for batch_id, row_status in document["pending"]]

    if state is None:
        if current == after:
            return _format_recovery_index_migration_state("unchanged", steps, after, True)
        if current != before:
            raise ValueError("current must equal before or after")
        status = None  # fresh from before
        confirmed = 0
    else:
        status, confirmed = _decode_recovery_index_migration_state(state, before, after, steps)
        if confirmed == len(steps):
            if current != after:
                raise ValueError("the migration is complete: current must equal after")
            return _format_recovery_index_migration_state(status, steps, after, True)
        if current != before:
            raise ValueError("the migration is unfinished: current must equal before")

    target = len(steps) if max_steps is None else min(len(steps), confirmed + max_steps)
    if target == len(steps):
        return _format_recovery_index_migration_state("applied", steps, after, True)
    return _format_recovery_index_migration_state("pending", steps[:target], before, False)
```

